{
    "name": "030_flux_concatenated_sequence_processing_with_split",
    "hf_id": "black-forest-labs/FLUX.1-Kontext-dev",
    "description": "Flux concatenated sequence processing pattern: concatenates text and image sequences, applies linear projection, then splits back. This pattern appears in dual-stream transformer blocks and represents a memory bandwidth bottleneck.",
    "axes": {
        "batch_size": {
            "type": "var",
            "description": "Batch size"
        },
        "text_seq_len": {
            "type": "var",
            "description": "Text/encoder sequence length"
        },
        "img_seq_len": {
            "type": "var",
            "description": "Image sequence length"
        },
        "hidden_dim": {
            "type": "const",
            "value": 3072,
            "description": "Hidden dimension size"
        }
    },
    "custom_inputs_entrypoint": null,
    "inputs": {
        "hidden_states": {
            "shape": [
                "batch_size",
                "img_seq_len",
                "hidden_dim"
            ],
            "dtype": "float32",
            "description": "Image latent sequence"
        },
        "encoder_hidden_states": {
            "shape": [
                "batch_size",
                "text_seq_len",
                "hidden_dim"
            ],
            "dtype": "float32",
            "description": "Text conditioning sequence"
        },
        "process_weight": {
            "shape": [
                "hidden_dim",
                "hidden_dim"
            ],
            "dtype": "float32",
            "description": "Linear projection weight matrix"
        }
    },
    "outputs": {
        "processed_encoder": {
            "shape": [
                "batch_size",
                "text_seq_len",
                "hidden_dim"
            ],
            "dtype": "float32",
            "description": "Processed encoder hidden states"
        },
        "processed_hidden": {
            "shape": [
                "batch_size",
                "img_seq_len",
                "hidden_dim"
            ],
            "dtype": "float32",
            "description": "Processed image hidden states"
        }
    },
    "reference": "import torch\n\n@torch.no_grad()\ndef run(\n    hidden_states: torch.Tensor,\n    encoder_hidden_states: torch.Tensor,\n    process_weight: torch.Tensor,\n) -> tuple[torch.Tensor, torch.Tensor]:\n    \"\"\"\n    Flux concatenated sequence processing pattern.\n    \n    1. Concatenate encoder_hidden_states and hidden_states along sequence dimension\n    2. Apply linear projection to the concatenated sequence\n    3. Split back into separate encoder and image streams\n    \n    Args:\n        hidden_states: Image latent sequence [batch, img_seq_len, hidden_dim]\n        encoder_hidden_states: Text conditioning sequence [batch, text_seq_len, hidden_dim]\n        process_weight: Linear projection weight [hidden_dim, hidden_dim]\n        \n    Returns:\n        Tuple of (processed_encoder_hidden_states, processed_hidden_states)\n    \"\"\"\n    text_seq_len = encoder_hidden_states.shape[1]\n    img_seq_len = hidden_states.shape[1]\n    \n    # Step 1: Concatenate sequences along sequence dimension\n    # Shape: [batch, text_seq_len + img_seq_len, hidden_dim]\n    concatenated = torch.cat([encoder_hidden_states, hidden_states], dim=1)\n    \n    # Step 2: Apply linear projection (no bias)\n    # processed = concatenated @ process_weight.T\n    processed = torch.matmul(concatenated, process_weight.t())\n    \n    # Step 3: Split back into separate streams\n    processed_encoder = processed[:, :text_seq_len, :]\n    processed_hidden = processed[:, text_seq_len:, :]\n    \n    return processed_encoder, processed_hidden\n"
}

